const raw = ($input.first().json.output ?? '').toString();
let parsed;
try {
  let txt = raw.trim();
  const m = txt.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : txt);
} catch (e) {
  parsed = { action: 'chat', reply: raw };
}
if (!parsed.action) parsed.action = 'chat';
if (parsed.action === 'chat' && !parsed.reply) parsed.reply = raw;
const bc = $('Build Context').first().json;
const chatId = bc.chatId;
const isVoice = bc.isVoice === true;
return [{ json: { action: parsed.action, to: parsed.to || '', subject: parsed.subject || '', body: parsed.body || '', reply: parsed.reply || '', location: parsed.location || '', chatId, isVoice } }];

const items = $input.all();
const chunks = [];
for (const it of items) {
  const j = it.json || {};
  let text = '';
  if (j.document && typeof j.document.pageContent === 'string') text = j.document.pageContent;
  else if (typeof j.pageContent === 'string') text = j.pageContent;
  else if (typeof j.text === 'string') text = j.text;
  if (text && text.trim()) chunks.push(text.trim());
}
const context = chunks.length
  ? chunks.map((c, i) => `[문서 ${i + 1}]\n${c}`).join('\n\n')
  : '(관련 등록 문서 없음)';
const prep = $('Prepare Input').first().json;
const userMessage = prep.query || '';
const chatId = prep.chatId;
const isVoice = prep.isVoice === true;
return [{ json: { userMessage, context, chatId, isVoice } }];

const trig = $('Telegram Trigger').first().json;
const chatId = trig.message && trig.message.chat ? trig.message.chat.id : null;
const j = $input.first().json || {};
let query = '';
let isVoice = false;
if (typeof j.text === 'string' && !j.message) {
  query = j.text;
  isVoice = true;
} else {
  query = (trig.message && trig.message.text) ? trig.message.text : '';
  isVoice = false;
}
return [{ json: { query, isVoice, chatId } }];

const item = $input.first();
const binary = item.binary || {};
if (binary.data) {
  binary.data.fileName = 'voice.ogg';
  binary.data.mimeType = 'audio/ogg';
}
return [{ json: item.json || {}, binary }];

const j=$input.first().json;
const M={'서울':'Seoul','부산':'Busan','대구':'Daegu','인천':'Incheon','광주':'Gwangju','대전':'Daejeon','울산':'Ulsan','세종':'Sejong','수원':'Suwon','성남':'Seongnam','고양':'Goyang','용인':'Yongin','부천':'Bucheon','춘천':'Chuncheon','강릉':'Gangneung','원주':'Wonju','청주':'Cheongju','천안':'Cheonan','전주':'Jeonju','목포':'Mokpo','여수':'Yeosu','순천':'Suncheon','포항':'Pohang','경주':'Gyeongju','구미':'Gumi','창원':'Changwon','진주':'Jinju','김해':'Gimhae','제주':'Jeju','서귀포':'Seogwipo','경기':'Suwon','강원':'Chuncheon','충북':'Cheongju','충남':'Cheonan','전북':'Jeonju','전남':'Mokpo','경북':'Pohang','경남':'Changwon'};
let loc=(j.location||'').trim();
const k=loc.replace(/(특별시|광역시|특별자치시|특별자치도|자치시|자치도|시|도|군|구)$/,'');
const q=M[loc]||M[k]||loc;
return [{ json: { q, region: loc, isVoice: j.isVoice===true, chatId: j.chatId } }];

const w=$input.first().json;
let prep={},pr={};
try{prep=$('Prep Weather').first().json;}catch(e){}
try{pr=$('Parse Response').first().json;}catch(e){}
const region=(prep.region||'').trim()||'요청하신 지역';
function wko(c){ if(c===0)return'맑음'; if(c<=2)return'대체로 맑음'; if(c===3)return'흐림'; if(c<=48)return'안개'; if(c<=57)return'이슬비'; if(c<=67)return'비'; if(c<=77)return'눈'; if(c<=82)return'소나기'; if(c<=86)return'눈 소나기'; return'천둥번개'; }
const c=w&&w.current, d=w&&w.daily;
let reply;
if(c&&typeof c.temperature_2m==='number'&&d){ reply=region+' 현재 '+Math.round(c.temperature_2m)+'도, '+wko(c.weather_code)+'이에요. 오늘 최고 '+Math.round(d.temperature_2m_max[0])+'도 최저 '+Math.round(d.temperature_2m_min[0])+'도, 강수확률은 '+d.precipitation_probability_max[0]+'%입니다.'; }
else { reply=region+' 날씨 정보를 찾지 못했어요. 큰 도시 이름으로 다시 말씀해 주시겠어요?'; }
return [{ json: { action:'chat', reply, isVoice: pr.isVoice===true, chatId: pr.chatId } }];

function findText(node){
  if(node==null) return '';
  if(typeof node==='string') return node;
  if(Array.isArray(node)){ for(const x of node){ const t=findText(x); if(t) return t; } return ''; }
  if(typeof node==='object'){
    if(node.type==='output_text' && typeof node.text==='string') return node.text;
    if(typeof node.text==='string' && node.text.trim() && !Array.isArray(node.content)) return node.text;
    if(Array.isArray(node.content)){ const t=findText(node.content); if(t) return t; }
    if(node.output){ const t=findText(node.output); if(t) return t; }
    if(node.message){ const t=findText(node.message); if(t) return t; }
  }
  return '';
}
const items=$input.all();
let desc='';
for(const it of items){ desc=findText(it.json); if(desc && desc.trim()){ desc=desc.trim(); break; } }
if(!desc) desc='사진 내용을 읽지 못했어요. 다시 보내주시겠어요?';
const chatId=$('Telegram Trigger').first().json.message.chat.id;
const sd=$getWorkflowStaticData('global');
sd['photo_'+chatId]=desc;
return [{ json:{ description:desc, chatId } }];

const chatId=$('Telegram Trigger').first().json.message.chat.id;
const sd=$getWorkflowStaticData('global');
const key='photo_'+chatId;
const text=sd[key]||'';
delete sd[key];
return [{ json: { text, found: !!text, chatId } }];
